const envelope = $json || {};
const body = envelope.body ?? envelope;
const data = body.data ?? body;
const key = data.key ?? body.key ?? {};

const instanceFromPath = envelope.params?.instance ?? envelope.pathParams?.instance ?? null;
const instanceName = instanceFromPath
  || body.instance_name
  || body.instanceName
  || body.instance
  || data.instanceName
  || data.instance
  || body?.instance?.instanceName
  || null;

const remoteJid = body.remoteJid
  || body.remote_jid
  || data.remoteJid
  || data.remote_jid
  || key.remoteJid
  || null;

const message = data.message ?? body.message ?? {};
const text = body.text
  || data.text
  || message.conversation
  || message.extendedTextMessage?.text
  || body.content
  || null;

return [
  {
    json: {
      ...body,
      data,
      key,
      instance_name: instanceName,
      instanceName,
      webhook_path_instance: instanceFromPath,
      remoteJid,
      remote_jid: remoteJid,
      text,
      professional_id: body.professional_id ?? body.professionalId ?? null,
      conversation_kind: body.conversation_kind ?? null,
      sender_kind: body.sender_kind ?? null,
      headers: envelope.headers ?? body.headers ?? {},
      query: envelope.query ?? {},
      received_at: new Date().toISOString()
    }
  }
];
